head.script:
scwin.__isBackground = function() {
    var color = WebSquare.wUnit.getJq("#gridView1_cell_1_2").css("background-color");
    if (color.indexOf("rgb") < 0) {
        return color == "#fca73c";
    }
    return color == "rgb(252, 167, 60)";
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_0_2').simulate('key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 name3항목의 33값을 마우스로 클릭한 후 EnterKey를 클릭한다.
    //1. After running the sample file, click the value 33 of the name3 entry with your mouse and click EnterKey.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 아래로 Key가 이동된다.(이전에는 아래로 Key가 이동되면서 edit모드로 설정됨)
    //1. The down key is moved (previously the down key is moved to the edit mode)
    WebSquare.wUnit.addCommand("assert", "scwin.__isBackground()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_'+$p.id+'gridView1__col3').css('display') != 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 14-Mar-2018
    //End unitTest
}
